from pages import list_page


def _all_pages(items, size):
    cursor = None
    out = []
    while True:
        page, next_cursor = list_page(items, cursor, size)
        out.extend(page)
        if next_cursor is None:
            return out
        cursor = next_cursor


def test_first_page_and_next_cursor_shape():
    items = [
        {"id": "b", "score": 1.0, "title": "B"},
        {"id": "a", "score": 2.0, "title": "A"},
    ]
    page, nxt = list_page(items, None, 1)
    assert page == [items[1]]
    assert nxt is not None
    assert isinstance(nxt, str)
    assert "title" not in nxt.lower() and "B" not in nxt and "A" not in nxt


def test_order_score_desc_then_id_asc():
    items = [
        {"id": "z", "score": 5.0},
        {"id": "a", "score": 5.0},
        {"id": "m", "score": 9.0},
    ]
    page, nxt = list_page(items, None, 10)
    assert [i["id"] for i in page] == ["m", "a", "z"]
    assert nxt is None


def test_walking_all_pages_returns_everything_once():
    items = [
        {"id": f"item-{i:03d}", "score": float(i % 3), "title": f"Item {i}"}
        for i in range(50)
    ]
    size = 7
    got = _all_pages(items, size)
    assert got == sorted(items, key=lambda x: (-x["score"], x["id"]))
    assert len(got) == len(items)
    ids = [i["id"] for i in got]
    assert len(set(ids)) == len(ids)


def test_size_one_walks_all():
    items = [{"id": str(i), "score": float(i % 4)} for i in range(20)]
    got = _all_pages(items, 1)
    assert [i["id"] for i in got] == [str(i) for i in range(20)]


def test_size_larger_than_collection():
    items = [{"id": "a", "score": 1.0}]
    page, nxt = list_page(items, None, 5)
    assert page == items
    assert nxt is None


